// Writes the stroke data and the font into components/kakijun/index.js (two generated blocks; do not edit them by hand).
//   node tools/kana-embed.mjs            regenerate both blocks
//   node tools/kana-embed.mjs --check    the data block equals data/kana/kana.json, and the font block decodes to the expected font
//
// kakijun-data: data/kana/kana.json made compact. Only what the part draws is kept, one character per line:
//   "あ":[count,[[d,end],…]]  or, for small kana, "ぁ":[count,[[d,end],…],{"yoko":[…],"tate":[…]}]  (place)
//   A stroke with measured ink widths (`w`, three widths along the stroke) is [d,end,w]; the part sizes its guard and narrow brush from it.
//   Notes, sources, base, loop and the other bookkeeping fields stay in kana.json.
//   var PUA = {"あ": [code points…]}: per-stroke glyphs of the font, for characters whose data has `pua` (none yet; then {}).
// kakijun-font: the woff2 subset "Egatari Kana" (derived from Klee One, SIL OFL 1.1; see data/kana/README.md "The font") as a
//   base64 data: URI. The font is not in the repository (data/kana/font/ is gitignored): when data/kana/font/<FONT_FILE> is
//   present it must have the sha256 below and is written in; when it is absent the block in index.js is kept. --check
//   decodes the block and compares its sha256 with FONT_SHA256, so the check needs no font file.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
export const JS = path.join(ROOT, 'components', 'kakijun', 'index.js');
export const JSON_FILE = path.join(ROOT, 'data', 'kana', 'kana.json');
export const FONT_FILE = 'EgatariKana-SemiBold-kana.woff2';
export const FONT_SHA256 = '5280a2910a9daaebe49d0b6e50af0a783733b326cbe3595bca9e9a43954538ae';
const sha = (b) => createHash('sha256').update(b).digest('hex');

const CREDIT = '// Egatari Kana — derived from Klee One. Copyright 2020 The Klee Project Authors (https://github.com/fontworks-fonts/Klee). Licensed under the SIL Open Font License 1.1 (see OFL.txt in this folder).';
const DATA_BEGIN = '// ---- BEGIN kakijun-data (generated by tools/kana-embed.mjs from data/kana/kana.json; do not edit) ----';
const DATA_END = '// ---- END kakijun-data ----';
const FONT_BEGIN = '// ---- BEGIN kakijun-font (generated by tools/kana-embed.mjs; do not edit) ----';
const FONT_END = '// ---- END kakijun-font ----';

// The compact form of one character, and back (the test compares the expansion with kana.json)
export function compact(c) {
  const s = c.strokes.map((x) => (x.w !== undefined ? [x.d, x.end, x.w] : [x.d, x.end]));
  return c.place ? [c.count, s, c.place] : [c.count, s];
}
export function expand(a) {
  const o = { count: a[0], strokes: a[1].map((x) => ({ d: x[0], end: x[1], ...(x.length > 2 ? { w: x[2] } : {}) })) };
  if (a[2]) o.place = a[2];
  return o;
}
export function dataBlock(data) {
  const lines = Object.entries(data.chars).map(([ch, c]) => JSON.stringify(ch) + ':' + JSON.stringify(compact(c)));
  return [DATA_BEGIN, `// ${Object.keys(data.chars).length} characters, data version ${data.version} (MIT; original stroke data, see data/kana/README.md)`,
    'var KANA = {', lines.join(',\n'), '};',
    // per-stroke glyphs (Private Use Area characters in Egatari Kana), when the data has them: "あ":[cp, …] in stroke order
    'var PUA = ' + JSON.stringify(Object.fromEntries(Object.entries(data.chars).filter(([, c]) => Array.isArray(c.pua)).map(([ch, c]) => [ch, c.pua]))) + ';', DATA_END].join('\n');
}
export function fontBlock(woff2) {
  return [FONT_BEGIN, CREDIT, `// ${FONT_FILE}, ${woff2.length} bytes, sha256 ${sha(woff2)}`,
    `var FONT = "data:font/woff2;base64,${woff2.toString('base64')}";`, FONT_END].join('\n');
}
const between = (src, a, b) => {
  const i = src.indexOf(a), j = src.indexOf(b);
  if (i < 0 || j < i) throw new Error(`${path.relative(ROOT, JS)}: no block ${a.slice(0, 40)}…`);
  return [i, j + b.length];
};
// The embedded data, read back from index.js (for tools/test-kakijun.mjs)
export function readEmbedded(src = fs.readFileSync(JS, 'utf8')) {
  const [i, j] = between(src, DATA_BEGIN, DATA_END);
  const body = src.slice(i, j).split('\n').filter((l) => !l.startsWith('//') && !l.startsWith('var PUA = ')).join('\n');
  const obj = JSON.parse(body.replace(/^var KANA = /, '').replace(/;\s*$/, ''));
  return Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, expand(v)]));
}
export function readFont(src = fs.readFileSync(JS, 'utf8')) {
  const [i, j] = between(src, FONT_BEGIN, FONT_END);
  const block = src.slice(i, j), m = block.match(/var FONT = "data:font\/woff2;base64,([A-Za-z0-9+/=]+)";/);
  return { block, credit: block.includes(CREDIT), woff2: m ? Buffer.from(m[1], 'base64') : null };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const data = JSON.parse(fs.readFileSync(JSON_FILE, 'utf8'));
  let src = fs.readFileSync(JS, 'utf8');
  const errs = [];
  const [di, dj] = between(src, DATA_BEGIN, DATA_END);
  const want = dataBlock(data);
  if (check) { if (src.slice(di, dj) !== want) errs.push('the kakijun-data block differs from data/kana/kana.json (run node tools/kana-embed.mjs)'); }
  else src = src.slice(0, di) + want + src.slice(dj);
  const fontPath = path.join(ROOT, 'data', 'kana', 'font', FONT_FILE);
  if (!check && fs.existsSync(fontPath)) {
    const b = fs.readFileSync(fontPath);
    if (sha(b) !== FONT_SHA256) { console.error(`kana-embed: ${fontPath} has sha256 ${sha(b)}, expected ${FONT_SHA256}`); process.exit(1); }
    const [fi, fj] = between(src, FONT_BEGIN, FONT_END);
    src = src.slice(0, fi) + fontBlock(b) + src.slice(fj);
  }
  const f = readFont(src);
  if (!f.woff2 || sha(f.woff2) !== FONT_SHA256) errs.push(`the kakijun-font block does not decode to ${FONT_FILE} (sha256 ${FONT_SHA256})`);
  if (!f.credit) errs.push('the kakijun-font block lacks the Klee One / OFL credit line');
  if (!f.block.includes(`sha256 ${FONT_SHA256}`)) errs.push('the kakijun-font block does not state the font sha256');
  if (!fs.existsSync(path.join(ROOT, 'components', 'kakijun', 'OFL.txt'))) errs.push('components/kakijun/OFL.txt is missing');
  if (errs.length) { errs.forEach((e) => console.log('FAIL ' + e)); process.exit(1); }
  if (!check) fs.writeFileSync(JS, src);
  console.log(`kana-embed${check ? ' --check' : ''}: ${Object.keys(data.chars).length} characters, font ${f.woff2.length} bytes: ok`);
}
